insert into public.cpl_memory (slug,kind,title,summary,tags,status,source,verified_by,verified_at,author,event_date) values
('d-handover-reviewer-sign-in-only-2026-11-20','decision','A hand-over takes a reviewer''s own sign-in, never the team phrase','S692 (SkyGannet), 2026-11-20, building Sam''s hand it over in place: only a signed-in reviewer hands something over. Supabase Storage cannot check the team phrase, and a hand-over is filed under a person''s name, so commons_handover_add() stamps handed_by from the sign-in and the page never sends it. Signed out, the box shows the sign-in alone. His to revise. Undo: git revert.',array['commons','hand-over','sign-in','privacy'],'proposed','kb/migrations/2026-11-20_commons_handover.sql; commons_handover.js; tests/commons_handover_sql_proof.py',null,null,'SkyGannet (S692)',date '2026-11-20'),
('d-handover-try-link-on-the-runner-2026-11-20','decision','Try the link starts the runner''s reader; the function fetches nothing','S692, 2026-11-20: Try the link saves the row, then the handover-try-link function checks the reviewer and dispatches commons-handover-pickup.yml with the row''s id. The function requests no address itself, so one reader visits a college''s site: CPLInitiativeCatalogCensus, robots.txt first, stopping at a bot check. With the function unreachable the link waits for the 05:41 UTC run.',array['commons','hand-over','reader','blocked-sources'],'proposed','chatbox/supabase/functions/handover-try-link/index.ts; kb/_handover_pickup.py; tests/handover_pickup_test.py',null,null,'SkyGannet (S692)',date '2026-11-20'),
('d-handover-slice-1-is-the-front-door-2026-11-20','decision','Hand-over slice 1 is the front door; filing into the datasets follows','S692, 2026-11-20: slice 1 takes a file, a link, pasted data or an API procedure, and the reader answers with a status and counts. It does not yet load outcomes into course_outcomes, save a link as the registry''s cor_url, or wire an API into a read: each is a guarded step in the commons lane''s NEXT. Until then a session files each hand-over by hand.',array['commons','hand-over','course-outlines','scope'],'proposed','docs/kb-notes/reference-commons-hand-over.md; docs/reference/lanes/commons.md',null,null,'SkyGannet (S692)',date '2026-11-20'),
('d-handover-college-goes-to-cdc-2026-11-20','decision','A college named in Needs you goes to College Data Collection''s panel','S692, 2026-11-20: Sam''s mock opens a college''s panel over whichever view is showing. Slice 1 sends the name to #collect/outlines-blocked/college/<slug>/handover, College Data Collection''s own panel on the hand-over pane, and Back to Needs you returns. Opening that panel over the front page with no change of view is step 6 of the lane''s NEXT. His to revise.',array['commons','hand-over','college-data-collection'],'proposed','commons_front.js; commons_data.js (handoverPane); tests/commons_handover.test.js (10)',null,null,'SkyGannet (S692)',date '2026-11-20'),
('f-handover-surfaces-dr-35-2026-11-20','fact','Hand-over surfaces and their governance row (DR-35)','S692, 2026-11-20: table commons_handover; private bucket commons-handover (one policy, a reviewer''s INSERT; no API read); rpc commons_handover_add (reviewer), commons_handover_mark (service role alone), commons_handover_summary (public counts, no person, file name, address or text); function handover-try-link; workflow commons-handover-pickup.yml. All mapped to DR-35.',array['commons','hand-over','governance','supabase'],'proposed','kb/governance_register.json (DR-35); kb/governance_surface_map.json; docs/reference/pipeline_reference.md section 8',null,null,'SkyGannet (S692)',date '2026-11-20'),
('p-fake-session-browser-script-denied-2026-11-20','pitfall','A browser script that fakes a reviewer session is denied; use npm run a11y','S692, 2026-11-20: an ad-hoc Playwright script that stood in a reviewer session and answered Supabase calls was denied by the permission check (undermining oversight). The sanctioned way to see a signed-in view is a seed in a11y.config.js (seedHandover follows seedFundingCurator) run with npm run a11y -- <target> --shots DIR. It found a skipped heading level the jsdom test could not.',array['a11y','permissions','testing','hand-over'],'proposed','a11y.config.js (seedHandover); the session''s own run, 2026-11-20',null,null,'SkyGannet (S692)',date '2026-11-20')
on conflict (slug) do nothing;

